import{_ as o,c as t,o as s,ah as n}from"./chunks/framework.D6otvB2a.js";const i="/assets/vscode-open-recent-dropdown.BLZc4U5S.png",c="/assets/vscode-open-folder-prompt-workspace.B-PzKkkH.png",r="/assets/vscode-open-workspace-popup.DEL7OCd-.png",a="/assets/vscode-recommended-extensions-popup.B6qrNv9H.png",p="/assets/vscode-command-palette.Cb2A4l5t.png",d="/assets/vscode-recommended-extensions-sidebar.DCbrLXMD.png",b=JSON.parse('{"title":"Per-Project Setup","description":"","frontmatter":{},"headers":[],"relativePath":"per-project-setup.md","filePath":"per-project-setup.md","lastUpdated":1787764669000}'),l={name:"per-project-setup.md"};function u(h,e,g,m,y,f){return s(),t("div",null,e[0]||(e[0]=[n('<h1 id="per-project-setup" tabindex="-1">Per-Project Setup <a class="header-anchor" href="#per-project-setup" aria-label="Permalink to &quot;Per-Project Setup&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page contains instructions for cloning a project&#39;s repository and getting it set up inside your dev container. You will need to complete these steps <strong>once per project</strong> in this course, after completing the <a href="/student-environment">Student Environment</a> setup and <a href="/github-repository-setup">creating your own repository</a> from the project&#39;s starter template.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Failure to follow the instructions on this page <strong>exactly</strong> as presented may result in corrupting your source code!</p></div><p>For each project in this course, you will first need to create your own private repository from the project&#39;s starter template by following the <a href="/github-repository-setup">Creating Your Project Repository</a> instructions. Once you have your repository, you will need to clone it. This will create a copy of the starter code and instructions on your local machine. For best results clone the repository from inside the dev container using <strong>one</strong> of the following methods:</p><ol><li>(Recommended) Open VS Code, select <code>File &gt; Open Recent</code>: <img src="'+i+'" alt="Open recent dropdown" data-zoomable="true"> and then select the <code>PATH_TO_DIRECTORY/student-env [Dev Container]</code> (Where <code>PATH_TO_DIRECTORY</code> is the actual path to the directory). Note that you <strong>must select the <code>[Dev Container]</code> entry</strong>!</li><li>Open VS Code, select <code>File &gt; Open Folder...</code>, navigate to the directory where you extracted the course dev container, and click on <code>Reopen in Container</code> popup (the same way you did for <a href="/student-environment#setup-the-course-dev-container">setting up the course dev container</a>).</li></ol><p>Now that you&#39;ve opened the dev container, open the top level of the workspace directory in the dev container by selecting <code>File &gt; Open Folder...</code>, navigate to the <code>/workspace/</code> directory, and click <code>Ok</code>:</p><p><img src="'+c+'" alt="Open folder prompt for the  directory" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you skip this step (which must be done each time you set up a new project), you may end up cloning repositories inside of each other, which will cause issues when committing and pushing changes to GitHub.</p></div><p>Once VS Code has opened/changed to the <code>/workspace/</code> directory, open the integrated terminal, and run the following command to clone your project repository:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PROJECT_REPOSITORY_URL</span></span></code></pre></div><p>Where <code>PROJECT_REPOSITORY_URL</code> is the URL of <strong>your own</strong> project repository (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code> if using HTTPS, or <code>git@github.com:USERNAME/project-1-USERNAME.git</code> if using SSH, where <code>USERNAME</code> is your GitHub username). You can find this URL by following the <a href="/github-repository-setup#find-your-repository-url">Find Your Repository URL</a> step of the <a href="/github-repository-setup">Creating Your Project Repository</a> instructions.</p><p>Once the repository is cloned, open the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) by clicking on it in the file explorer. You should see a popup notification, typically on the bottom right of the window, that says <code>Open Workspace</code>:</p><p><img src="'+r+'" alt="Open Workspace popup" data-zoomable="true"></p><p>Click on <code>Open Workspace</code> to open the project-specific workspace (This will change VS Code&#39;s working directory to the project directory and load the project-specific settings). Once the workspace is open, you may get yet another notification asking if you would like to install the recommended extensions for the workspace:</p><p><img src="'+a+'" alt="Install recommended extensions popup" data-zoomable="true"></p><p>Click on <code>Install</code> to install the recommended extensions. Alternatively, you can install the recommended workspace extensions by pressing <code>CTRL+SHIFT+P</code> (or <code>CMD+SHIFT+P</code> on Mac) to open the command palette:</p><p><img src="'+p+'" alt="Command palette" data-zoomable="true"></p><p>Then, type <code>Extensions: Show Recommended Extensions</code>, and press <code>Enter</code>. Then, click on the cloud icon with a down arrow to install all recommended extensions:</p><p><img src="'+d+`" alt="Extensions sidebar with recommended extensions" data-zoomable="true"></p><p>Once the extensions are installed, you can now start working on your project! Note that the <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) we provide is pre-configured with everything you need for one-click building/debugging. You can find more information on how to use the workspace file in the each project&#39;s <code>README.md</code> file.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>As you work on the project, remember to periodically commit and push your changes (e.g.: <code>git add</code>, <code>git commit</code>, and <code>git push</code>). Committing and pushing often protects your work in case something happens to your dev container, and gives you a history of checkpoints you can go back to if you need to.</p></div><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="cloning-using-https-instead-of-ssh" tabindex="-1">Cloning Using HTTPS Instead of SSH <a class="header-anchor" href="#cloning-using-https-instead-of-ssh" aria-label="Permalink to &quot;Cloning Using HTTPS Instead of SSH&quot;">​</a></h3><ul><li>Symptom: you receive an error message when cloning a repository similar to:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fatal: could not read Username for &#39;https://github.com&#39;: terminal prompts disabled</span></span>
<span class="line"><span>remote: Repository not found.</span></span></code></pre></div><ul><li>Solution: clone using the SSH URL (e.g.: <code>git@github.com:USERNAME/project-1-USERNAME.git</code>) instead of the HTTPS URL (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code>).</li></ul><h3 id="cloning-using-ssh-instead-of-https-ssh-key-not-set-up-correctly" tabindex="-1">Cloning Using SSH Instead of HTTPS/SSH Key Not Set Up Correctly <a class="header-anchor" href="#cloning-using-ssh-instead-of-https-ssh-key-not-set-up-correctly" aria-label="Permalink to &quot;Cloning Using SSH Instead of HTTPS/SSH Key Not Set Up Correctly&quot;">​</a></h3><ul><li>Symptom: you receive an error message when cloning a repository similar to:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git@github.com: Permission denied (publickey).</span></span>
<span class="line"><span>fatal: Could not read from remote repository.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please make sure you have the correct access rights</span></span>
<span class="line"><span>and the repository exists.</span></span></code></pre></div><ul><li>Solution: if you are intending on using HTTPS, use the HTTPS URL (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code>). If you are intending on using SSH, make sure you set up your SSH key correctly by following the instructions in the <a href="/student-environment#setup-git-inside-the-dev-container">Setup Git Inside the Dev Container</a> section.</li></ul><h3 id="can-t-find-the-project-specific-code-workspace-file-e-g-project-1-code-workspace" tabindex="-1">Can&#39;t Find The Project-Specific <code>*.code-workspace</code> File (e.g.: <code>project-1.code-workspace</code>) <a class="header-anchor" href="#can-t-find-the-project-specific-code-workspace-file-e-g-project-1-code-workspace" aria-label="Permalink to &quot;Can&#39;t Find The Project-Specific \`*.code-workspace\` File (e.g.: \`project-1.code-workspace\`)&quot;">​</a></h3><ul><li>Symptom: you can&#39;t find the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) in VS Code&#39;s file explorer.</li><li>Solution: make sure you have opened the top level of the workspace directory in the dev container (See the instructions above for more details).</li></ul><h3 id="missing-debug-configurations-tools" tabindex="-1">Missing Debug Configurations/Tools <a class="header-anchor" href="#missing-debug-configurations-tools" aria-label="Permalink to &quot;Missing Debug Configurations/Tools&quot;">​</a></h3><ul><li>Symptom: the VS Code debug configurations and/or build/debug tools (e.g.: <code>clang</code>, <code>cmake</code>, <code>gcc</code>, <code>g++</code>, <code>make</code>, etc.) are missing.</li><li>Solution: double check you have opened the course dev container <strong>first</strong>, and then opened the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) <strong>second</strong>. If you open the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) without first opening the course dev container (or in different dev container), the debug configurations and/or tools will be missing.</li></ul>`,34)]))}const w=o(l,[["render",u]]);export{b as __pageData,w as default};
